// Free trial emails: login, copy to us, reminder before the trial ends, follow-up once it has ended.
// The customer emails share one design with every other trial site; their HTML comes from
// lib/trial-kit.js (generated by trial-emails/build.mjs). This file adds subjects and plain-text parts.
import { allPlans } from '../src/site.mjs';
import { kitWelcome, kitReminder, kitFollowup } from './trial-kit.js';

const SITE = 'https://mojo4k.uk';
export const SUPPORT = 'help@mojo4k.uk';

export const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);

// Every server URL, numbered when there is more than one (older records only have `server`).
const serverList = (l) => (l.servers && l.servers.length ? l.servers : [l.server]);
const serverLabel = (l, i) => (serverList(l).length > 1 ? `Server URL ${i + 1}` : 'Server URL');

const first = (name) => String(name || '').trim().split(/\s+/)[0] || '';

// Plain-text login: username and password first, then the server URLs, then the M3U link.
const loginText = (l) => `Username: ${l.username}
Password: ${l.password}
${serverList(l).map((s, i) => `${i ? 'Backup server URL (only if the first one does not connect)' : 'Server URL'}: ${s}`).join('\n')}

Or, if your app asks for one playlist link:
M3U URL: ${l.m3u}

These are not website links: enter them in an IPTV app (IPTV Smarters Pro, TiviMate or IBO Player), not in a browser.`;

const termLabel = (m) => (m === 1 ? '1 month' : m === 12 ? '12 months' : `${m} months`);
const plansText = () => {
  const plans = allPlans();
  return [...new Set(plans.map((p) => p.devices))].map((d) => `${d} device${d > 1 ? 's' : ''}
${plans.filter((p) => p.devices === d).map((p) => `${termLabel(p.months)}: £${p.price}  ${SITE}/${p.slug}/`).join('\n')}`).join('\n\n');
};

// ---- 1. Customer: the login ----
export const loginEmail = (name, l) => ({
  subject: 'Your MOJO 4K free trial',
  html: kitWelcome(name, l),
  text: `${first(name) ? `Hi ${first(name)},` : 'Hi there,'}

Welcome to MOJO 4K. Your free trial is active${l.expire ? ` until ${l.expire}` : ' for the next 24 hours'}.

Your login details:

${loginText(l)}

1. Install an IPTV app.
2. Choose Xtream Codes and copy in the username, password and server URL, or paste the M3U URL.
3. Press play. Setup guides: ${SITE}/iptv-setup-guides/

Help on WhatsApp: ${SITE}/go/wa
Plans: ${SITE}/pricing/`,
});

// ---- 2. Copy to us ----
export const adminEmail = (t) => ({
  subject: `Automation / mojo4k.uk / trial / ${t.name || 'No name'} / ${t.email || 'No email'}`,
  text: `New automatic free trial on mojo4k.uk

Name: ${t.name || '-'}
Email: ${t.email || '-'}
WhatsApp: ${t.phone || '-'}
Notes: ${t.notes || '-'}
Customer email sent: ${t.emailed ? 'yes' : 'NO (shown on screen instead)'}
Reminder scheduled: ${t.reminder ? "yes" : "no"} · Follow-up scheduled: ${t.followup ? "yes" : "no"}

${serverList(t).map((s, i) => `${serverLabel(t, i)}: ${s}`).join('\n')}
Username: ${t.username}
Password: ${t.password}
Expires: ${t.expire || '-'}
M3U: ${t.m3u}
Panel user id: ${t.userId || '-'}
Created: ${t.created}`,
});

// ---- 3. Customer: reminder before the trial ends ----
export const reminderEmail = (name, l) => ({
  subject: 'Your MOJO 4K free trial ends soon',
  html: kitReminder(name, l),
  text: `Your MOJO 4K free trial ends in about 4 hours. Subscribe now and keep the same login.

Choose your plan (each link goes straight to that plan):

${plansText()}

Your login details (still the same):
${loginText(l)}

WhatsApp: ${SITE}/go/wa`,
});

// ---- 4. Customer: follow-up once the trial has ended ----
export const followupEmail = (name) => ({
  subject: 'Your MOJO 4K free trial has ended',
  html: kitFollowup(name),
  text: `Your MOJO 4K free trial has ended. Subscribe today and you are back on the same login within minutes.

Choose your plan (each link goes straight to that plan):

${plansText()}

Questions? WhatsApp: ${SITE}/go/wa`,
});
